  v_zero_match_rows BIGINT;
  v_multi_match_rows BIGINT;
BEGIN
  IF to_regclass('public.member_documents') IS NULL THEN
    RAISE NOTICE 'RLS 0010: member_documents absent — skipping PART 5a tenant-column prerequisite';
    RETURN;
